<script lang="ts">
  // /about (PLAN §7): how similarity works, the evaluation record, data notes, hosting, attribution, how to read a
  // pyramid. Every number on this page is read from web/src/data/evals.json (scripts/export_evals.py, regenerated by
  // `make build`) or meta.json — nothing is typed in by hand, so a re-run of the evaluation re-writes the page.
  import { countries, meta } from '../lib/entities.ts';
  import { dataUrl } from '../lib/data.ts';
  import { evals, fmt, fmtPctOf, g1Of, g2Of, imageSpace, orderedMetrics } from '../lib/evals.ts';
  import { METRIC_LABEL } from '../lib/restate.ts';
  import { href } from '../lib/url.ts';
  import { app } from '../lib/state.svelte.ts';
  import { countryQuery, type Metric } from '../lib/router.ts';

  const sigma = meta.sigma;
  const sL2 = sigma.l2['2'];
  const sW1 = sigma.w1sex['2'];
  const sL2t = sigma.l2['1'];
  const sW1t = sigma.w1['1'];
  const nAgg = meta.n_entities - meta.n_countries;
  const nMicro = countries.filter((e) => e.is_micro).length;
  const patch = meta.patches[0] ?? null;
  const exposed = evals.exposed_visual;
  const exposedSpace = exposed ? imageSpace(exposed.model) : undefined;
  const gate = evals.prereg.continuity_gate;
  const visualRows = evals.g1.filter((r) => r.metric.startsWith('visual:'));
  const w1 = g1Of('w1');
  const blend = g1Of('blend');
  const share = evals.blend_w1_share;
  const presets = evals.div_presets ?? { strict: 0, balanced: 0.5, spread: 2 };
  const sweep = evals.beta_sweep ?? [];
  const eraChip = (y: number) => `${y} ${y > app.currentYear ? '(projected)' : y > meta.last_observed_year ? '(nowcast)' : ''}`.trim();
  const menuLabel = (m: string): string => (m.startsWith('visual:') ? `Visual · ${m.slice(7)}` : (METRIC_LABEL[m as Metric] ?? m));
  const example = (id: string, year: number) => href(countryQuery(id, year));
  const noticeUrl = dataUrl(meta.files.notice);
  const built = meta.built.slice(0, 10);
  const evalBuilt = evals.built.slice(0, 10);

  const SECTIONS = [
    ['similarity', 'How similarity works'],
    ['visual', 'The Visual metric'],
    ['record', 'Evaluation record'],
    ['data', 'Data notes'],
    ['projections', 'Why projections converge'],
    ['development', 'Shape is not development'],
    ['reading', 'How to read a pyramid'],
    ['hosting', 'Hosting & privacy'],
    ['attribution', 'Attribution & licences'],
  ] as const;
</script>

<article class="mx-auto max-w-3xl py-6 leading-relaxed">
  <h1 class="text-3xl font-semibold tracking-tight">About</h1>
  <p class="mt-2 text-fg-2">
    Population Pyramid Explorer shows the age structure of {meta.n_countries} countries and {nAgg} regions for every year
    1950–2100, and finds the pyramids most and least like any of them <em>by shape</em>. This page says exactly how,
    with the measured numbers the site itself was built from (data built {built}; evaluation run {evalBuilt}, stage
    “{evals.stage}”).
  </p>
  <nav aria-label="On this page" class="mt-4 flex flex-wrap gap-x-3 gap-y-1 text-sm">
    {#each SECTIONS as [id, label] (id)}
      <a class="underline decoration-border underline-offset-2 hover:decoration-fg" href="#{id}">{label}</a>
    {/each}
  </nav>

  <!-- ============================================================ similarity -->
  <section id="similarity" class="mt-10 space-y-4">
    <h2 class="text-xl font-semibold tracking-tight">How similarity works</h2>
    <p>
      <strong>Shape</strong> is a vector of 42 numbers: the share of the total population in each of 21 five-year age
      bands (0–4 … 95–99, 100+), separately for males and females. Dividing by the total makes the comparison
      size-invariant — Niger and India can be neighbours — but not age-shift-invariant (an older population is a
      different shape) and not sex-swap-invariant (Qatar's male working-age bulge is shape). Shares are never
      re-scaled per bin and never smoothed in storage.
    </p>
    <h3 class="font-semibold">The default metric, “Shape” (<code>blend</code>)</h3>
    <p>Two halves, each divided by its typical value so neither dominates:</p>
    <pre class="overflow-x-auto rounded-md border border-border bg-surface p-3 text-sm"><code>l2   = ‖s42_a − s42_b‖₂                          (bin-by-bin difference)
w1s  = 5 · Σ_k |CM_a,k − CM_b,k| + |CF_a,k − CF_b,k|   (per-sex age movement, in years)
d    = ½ · l2 / σ_L2  +  ½ · w1s / σ_W1
σ_L2 = {fmt(sL2, 4)}   σ_W1 = {fmt(sW1, 3)} y         (two-sex; total-only: {fmt(sL2t, 4)} / {fmt(sW1t, 3)} y)</code></pre>
    <p>
      <code>CM</code>/<code>CF</code> are the cumulative male and female shares up the age ladder, so the second term
      is a Wasserstein-1 (“earth-mover”) distance: how many years of age, on average, the mass of one pyramid has to
      travel to become the other. The σ values are the <em>median distance between random pairs of countries in the same
      year</em>, measured on this corpus at build time, so <code>d = 1</code> means “as far apart as a typical pair”.
      The L2 half is blind to <em>where</em> a difference sits; the W1 half charges a shifted bulge in proportion to how
      far it moved. Every result card decomposes its <code>d</code> into the two halves and the three bins that
      contribute most to each, and the “similar because / differs in” sentences compare summary features (median age,
      65+, under-15, base slope, working-age sex ratio, modal band) z-scored against <em>the query year's</em> country
      set — for both members of a pair, whatever the candidate's year, so a sentence about South Korea 2026 and Japan
      2008 reads the same from a country page and from the compare page.
    </p>

    <h3 class="font-semibold">Why plain age-shift (<code>w1</code>) is not the default</h3>
    <p>
      The one-number Wasserstein distance on the total age distribution is the most interpretable option (“1.97 years
      of average age movement separates them”), and it stays in the menu as <em>{METRIC_LABEL.w1}</em>. It is not the
      default because it collapses to roughly |Δ mean age| and is sex-blind: two pyramids with the same mean age but
      opposite base slopes read as identical. It also failed the continuity gate — the year-to-year nearest neighbour
      of a country is that same country only C1 = {fmt(w1?.c1_obs)} of the time (gate ≥ {gate.c1}; Shape: {fmt(blend?.c1_obs)}),
      so its verdict is “{evals.verdicts.w1?.verdict}” in the record below.
    </p>

    <h3 class="font-semibold">A documented asymmetry in the per-sex term</h3>
    <p>
      The per-sex W1 is unbalanced: male and female shares of the <em>total</em> do not sum to the same mass, and the
      surplus is parked at the 100+ end. A young male surplus (Gulf states) therefore pays roughly 13 bands × 5 years of
      transport, while an elderly female surplus (Japan 80+) pays almost nothing, and both <code>CM</code> and
      <code>CF</code> carry the imbalance. A balanced alternative (<em>{METRIC_LABEL.w1bal}</em>, total-distribution W1 plus a
      sex-ratio term) is under “advanced”. Because σ is fitted over all years pooled, the two halves of Shape are equal
      only on the pooled sample:
    </p>
    {#if share}
      <div class="overflow-x-auto">
        <table class="w-full text-sm">
          <caption class="sr-only">Median W1 share of the Shape distance by era</caption>
          <thead class="text-left text-xs text-muted"><tr><th class="py-1 pr-3 font-medium">sex</th><th class="py-1 pr-3 font-medium">observed ≤ {meta.last_observed_year}</th><th class="py-1 pr-3 font-medium">nowcast</th><th class="py-1 pr-3 font-medium">projected</th><th class="py-1 font-medium">pooled (σ fit)</th></tr></thead>
          <tbody>
            {#each Object.entries(share) as [sex, row] (sex)}
              <tr class="border-t border-border tabular-nums"><td class="py-1 pr-3">{sex === '2' ? 'two-sex' : 'total only'}</td><td class="py-1 pr-3">{fmt(row.obs, 3)}</td><td class="py-1 pr-3">{fmt(row.nowcast, 3)}</td><td class="py-1 pr-3">{fmt(row.proj, 3)}</td><td class="py-1">{fmt(row.all, 3)}</td></tr>
            {/each}
          </tbody>
        </table>
      </div>
      <p class="text-sm text-fg-2">
        σ_W1 rises into the projections, which tilts observed-year pairs slightly towards the L2 half. The definition
        stands (it is balanced at the 2024–2026 default years); the tilt is recorded rather than hidden.
      </p>
    {/if}

    <h3 class="font-semibold">Trend: motion and path</h3>
    <p>
      The <em>Trend</em> mode compares change instead of a snapshot, over a window L of 5, 10 or 20 years.
      <strong>Motion</strong> is the distance between the two L-year changes in the 42 shares (who is moving the same
      way, regardless of where they are; σ<sub>trend@10</sub> = {fmt(sigma['trend@10']?.['2'], 4)}). <strong>Path</strong> is the
      mean Shape distance over the aligned L-year path (who is at the same place <em>and</em> moving the same way). Both
      passed continuity (motion C1 {fmt(g1Of('trend')?.c1_obs)}, path {fmt(g1Of('path')?.c1_obs)}); motion is a
      level-free signal, so it disagrees with every snapshot label set by construction and is offered for what it is.
    </p>

    <h3 class="font-semibold">“Most different” and diversity</h3>
    <p>
      Opposites are the farthest pyramids under the active metric over the same candidate set as the twins,
      <em>diversified</em> with a maximal-marginal-relevance step: the pool is the farthest quartile; the first choice is
      the farthest; each next choice maximises <code>d(q, x) + β · min_s d(x, s)</code> against the choices so far. Three
      presets: strict (β = {presets.strict}) is plain farthest-k, balanced (β = {presets.balanced}, default) keeps about
      two thirds of the strict list, spread (β = {presets.spread}) about a third. <strong>The raw rank is never
      hidden</strong>: every opposite card says “#7 farthest”, and a strip under the cards lists the strictly farthest
      set whenever diversity changed it.
    </p>
    {#if sweep.length}
      <div class="overflow-x-auto">
        <table class="w-full text-sm">
          <caption class="sr-only">β sweep on the 2024 country anchors</caption>
          <thead class="text-left text-xs text-muted"><tr><th class="py-1 pr-3 font-medium">β</th><th class="py-1 pr-3 font-medium">top-5 Jaccard vs strict</th><th class="py-1 pr-3 font-medium">mean raw rank</th><th class="py-1 font-medium">mean UN regions among 5</th></tr></thead>
          <tbody>
            {#each sweep as r (r.beta)}
              <tr class="border-t border-border tabular-nums"><td class="py-1 pr-3">{r.beta}</td><td class="py-1 pr-3">{fmt(r.jaccard_vs_strict, 2)}</td><td class="py-1 pr-3">{fmt(r.mean_raw_rank, 1)}</td><td class="py-1">{fmt(r.mean_regions, 2)}</td></tr>
            {/each}
          </tbody>
        </table>
      </div>
      <p class="text-sm text-fg-2">
        Diversity works over <em>shape</em> distance, not region or class: for an old anchor the farthest quartile is
        entirely young Sahel and Gulf pyramids, so no β yields regional variety (mean regions stays near 2 at every β).
        The site therefore never promises it.
      </p>
    {/if}

    <h3 class="font-semibold">Percentile bands</h3>
    <p>
      “very close / close / typical / far / extreme” place a distance against the right null: for a same-year pair, the
      distribution of random country pairs <em>in that year</em> (the scale drifts — random pairs were closer in 1950
      and will be closer again by 2100 as projections converge, so pooled tables would mislabel both ends); for a
      cross-year pair, random pairs with the query's decade and era; for a time-shift row, the distribution of
      <em>best-year</em> matches, which is what “closer than 93 % of best-year matches” means. Cut-points are p5 / p25 /
      p75 / p95 on a {meta.bands_grid.length}-point quantile grid; percentiles are interpolated and shown as “≈”.
    </p>
  </section>

  <!-- ============================================================ visual -->
  <section id="visual" class="mt-10 space-y-4">
    <h2 class="text-xl font-semibold tracking-tight">The Visual metric — a pre-registered experiment</h2>
    <p>
      The tempting shortcut is to render every pyramid, embed the picture with a vision model and retrieve nearest
      pictures. It was tested as an experiment with the gates written down first (<code>evals/image_embeddings.md</code>),
      not adopted as the architecture. Two encoders were run on text-free canonical renders of all {evals.n_rows.toLocaleString('en-US')}
      pyramids — SigLIP 2 (base, naflex, one 16-px patch row per age band) and DINOv2 (base) — pooled, L2-normalised and
      reduced to 64 dimensions without whitening. Continuity gate: {gate.definition}; gate C1 ≥ {gate.c1}, C5 ≥ {gate.c5} on {gate.span}.
    </p>
    <h3 class="font-semibold">Pre-registered predictions</h3>
    <div class="overflow-x-auto">
      <table class="w-full text-sm">
        <caption class="sr-only">Pre-registered predictions for the image-embedding experiment</caption>
        <thead class="text-left text-xs text-muted"><tr><th class="py-1 pr-3 font-medium">id</th><th class="py-1 pr-3 font-medium">prediction</th><th class="py-1 pr-3 font-medium">gate</th><th class="py-1 font-medium">measured</th></tr></thead>
        <tbody>
          {#each evals.prereg.image_predictions as p (p.id)}
            {@const scored = evals.image_spaces.map((s) => ({ model: s.model, hit: s.predictions_scored.find((q) => q.id === p.id || q.id.split('/').includes(p.id)) }))}
            <tr class="border-t border-border align-top">
              <td class="py-1 pr-3 font-mono text-xs">{p.id}</td>
